package com.meterflow.notifications;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.scheduling.annotation.Scheduled;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
@Service public class WebhookDeliveryService{private final WebhookRepository hooks;private final WebhookDeliveryRepository deliveries;private final ObjectMapper mapper;private final HttpClient client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build();public WebhookDeliveryService(WebhookRepository h,WebhookDeliveryRepository d,ObjectMapper m){hooks=h;deliveries=d;mapper=m;}
@Transactional public void publish(String customer,String type,Map<String,Object> data){try{String payload=mapper.writeValueAsString(Map.of("id",UUID.randomUUID().toString(),"type",type,"createdAt",Instant.now().toString(),"data",data));for(var h:hooks.findByCustomerIdAndActiveTrue(customer))deliveries.save(new WebhookDelivery(h.getId(),type,payload));}catch(Exception e){throw new IllegalStateException("Could not create webhook delivery",e);}}
@Scheduled(fixedDelay=15000)public void dispatchDue(){for(var d:deliveries.findByStatusAndNextAttemptAtBefore("PENDING",Instant.now()))dispatch(d.getId());}
@Transactional public void dispatch(UUID id){var d=deliveries.findById(id).orElseThrow();if(!"PENDING".equals(d.getStatus())||d.getNextAttemptAt().isAfter(Instant.now()))return;var h=hooks.findById(d.getWebhookId()).orElse(null);if(h==null){d.failure("Webhook endpoint removed");return;}try{URI uri=URI.create(h.getEndpoint());String host=uri.getHost();if(host==null||uri.getUserInfo()!=null||!("https".equalsIgnoreCase(uri.getScheme())||"http".equalsIgnoreCase(uri.getScheme()))||!isPublicHost(host)){d.failure("Rejected unsafe or invalid endpoint");return;}String sig=sign(d.getPayload(),h.getSecret());var req=HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(5)).header("Content-Type","application/json").header("X-MeterFlow-Event",d.getEventType()).header("X-MeterFlow-Signature","sha256="+sig).POST(HttpRequest.BodyPublishers.ofString(d.getPayload())).build();var response=client.send(req,HttpResponse.BodyHandlers.ofString());if(response.statusCode()>=200&&response.statusCode()<300)d.success("HTTP "+response.statusCode());else d.failure("HTTP "+response.statusCode()+": "+response.body().substring(0,Math.min(700,response.body().length())));}catch(Exception ex){d.failure(ex.getClass().getSimpleName()+": "+String.valueOf(ex.getMessage()));}}
private boolean isPublicHost(String host){try{for(var address:InetAddress.getAllByName(host)){if(address.isAnyLocalAddress()||address.isLoopbackAddress()||address.isLinkLocalAddress()||address.isSiteLocalAddress()||address.isMulticastAddress())return false;}return true;}catch(Exception e){return false;}}
private String sign(String payload,String secret)throws Exception{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return HexFormat.of().formatHex(mac.doFinal(payload.getBytes(StandardCharsets.UTF_8)));}
public List<WebhookDelivery> all(UUID hook){return deliveries.findByWebhookIdOrderByCreatedAtDesc(hook);}public WebhookDelivery replay(UUID id){var d=deliveries.findById(id).orElseThrow();d.replay();return deliveries.save(d);}}
